'use client';

import * as React from 'react';

// @interlace/button v3.6.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/button
// What changed since: https://ds.interlace.tools/c/button#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — Button (secondary reference for the interlace-component skill)
 *
 * The minimal-surface counterpart to [dialog.tsx](./dialog.tsx). Where Dialog
 * exercises compound composition + portal + focus, Button exercises the
 * variant + render-prop polymorphism + native-event passthrough surface.
 *
 * | Rule | Concept                          | Where in this file                                                          |
 * | ---- | -------------------------------- | --------------------------------------------------------------------------- |
 * | R4   | Extends native el + VariantProps | `React.ComponentProps<'button'> & VariantProps<typeof buttonVariants>`      |
 * | R7   | className merged + ...rest + ref | `cn(buttonVariants({ ... }), className)` + `{...props}` + `useRender`        |
 * | R8   | No `isXxx` prefix                | All variant keys (`variant`, `size`) follow MUI naming, not `isXxx`         |
 * | R9   | Native onClick stays native      | `onClick` passes through `{...props}` — never wrapped in a bespoke name     |
 * | R12  | Reuse over wrap                  | The `render` prop lets consumers replace the rendered element entirely      |
 * | R13  | Ecosystem first                  | `useRender` from `@base-ui/react/use-render` owns slot rendering |
 * | R17  | API parity                       | Mirrors shadcn/ui Button + Base UI's `useRender` slot — no deviation        |
 * | R18  | Tailwind only                    | Zero inline `style={{}}`; all visual classes come from `buttonVariants`     |
 * | R19  | Tokens only                      | `buttonVariants` lives in [button-variants.ts](./button-variants.ts) and uses theme tokens |
 * | R20  | AA contrast                      | Variant classes target `bg-primary`/`text-primary-foreground` — token pair  |
 * | R26  | A11y from native el              | `<button>` is the native element; focus, keyboard, ARIA inherited           |
 *
 * ## Loading
 *
 * `loading` keeps the button where it is and as wide as it was, and says it
 * is busy. The label and any direct icon stay in the layout but stop
 * painting (`-webkit-text-fill-color: transparent` and `invisible`), and a
 * spinner sits over the middle in the label's own colour, so nothing beside
 * the button shifts. The button stays focusable: it takes `aria-busy` and
 * `aria-disabled`, not `disabled`, because a focused button that becomes
 * `disabled` drops focus to the page. Clicks are swallowed while it loads,
 * including a form submit. Under reduced motion the spinner stands still,
 * which still reads as "working".
 *
 * Out of scope: this primitive does not own `data-testid` / `data-slot` defaults
 * (R5 / R6) — those are consumer-supplied and live one level up in the
 * compound parent (`<MyButton data-testid="submit" data-slot="form-submit">`).
 */

import { useRender } from '@base-ui/react/use-render';
import type { VariantProps } from 'class-variance-authority';
import { LoaderCircleIcon } from 'lucide-react';

import { cn } from '@/lib/utils';
import { buttonVariants } from '@/components/ui/button-variants';

type ButtonProps = React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    /**
     * Replace the rendered element. Equivalent to shadcn's legacy `asChild`.
     * Pass a `ReactElement` (e.g. `<Link href="...">`) or a render function.
     */
    render?: useRender.RenderProp;
    /**
     * Busy: show a spinner over the label, keep the size and focus, and
     * ignore clicks until it is false again. The click still bubbles, as it
     * does for any `aria-disabled` control, so a clickable parent should
     * check `aria-busy` if it must ignore it too.
     */
    loading?: boolean;
    /**
     * Stretch to the width of the container (form actions, mobile CTAs).
     * Prefer this over `className="w-full"`.
     * @default false
     */
    fullWidth?: boolean;
    /**
     * Native button type. Unlike a bare `<button>`, Button does NOT submit by
     * default: pass `type="submit"` for the form's submit action.
     * @default 'button' (no default when `render` replaces the element)
     */
    type?: 'button' | 'submit' | 'reset';
  };

/**
 * The label stops painting but keeps its space. Text through the fill colour
 * (`currentColor` still reaches the spinner), direct icons through
 * `invisible`. The spinner's icon sits inside a span, out of both reaches,
 * and a span keeps Button's `has-[>svg]` padding from seeing it.
 */
const LOADING = '[-webkit-text-fill-color:transparent] [&>svg]:invisible cursor-progress';

function swallow(event: React.MouseEvent) {
  event.preventDefault();
}

function Button({
  className,
  variant = 'default',
  size = 'default',
  fullWidth = false,
  render,
  loading = false,
  type,
  ...props
}: ButtonProps) {
  const { children } = props;
  const element = useRender({
    render: render ?? <button />,
    props: {
      'data-slot': 'button',
      'data-variant': variant ?? undefined,
      'data-size': size ?? undefined,
      className: cn(buttonVariants({ variant, size, fullWidth }), loading && LOADING, className),
      // A native <button> defaults to type="submit", so a Cancel inside a form
      // submitted it. Default to "button" (MUI ButtonBase, Chakra, Primer do the
      // same); submitting is now an explicit `type="submit"`. A `render`ed
      // element (an <a>, a router Link) gets no type unless one is passed.
      type: type ?? (render ? undefined : 'button'),
      ...props,
      ...(loading && {
        'data-loading': '',
        'aria-busy': true,
        'aria-disabled': true,
        onClick: swallow,
        // Only while loading: otherwise `children` rides in `...props`, so a
        // `render` element keeps its own children.
        children: (
          <>
            {children}
            <span
              data-slot="button-spinner"
              aria-hidden
              className="absolute inset-0 grid place-items-center"
            >
              <LoaderCircleIcon className="size-4 motion-safe:animate-spin" />
            </span>
          </>
        ),
      }),
    },
  });

  return element;
}

export { Button, buttonVariants };
export type { ButtonProps };

import { cva, type VariantProps } from 'class-variance-authority';

// @interlace/button-variants v3.5.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/button-variants
// What changed since: https://ds.interlace.tools/c/button-variants#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — buttonVariants
 *
 * The cva variant map that `button.tsx` imports — variant × size class strings
 * and nothing else. Pure CVA: no React, no client APIs, so a server component
 * can style a plain `<a>` with `buttonVariants({ variant, size })`.
 *
 * This is not a component. It exports a function and a type, renders nothing,
 * and has no props, no slots and no DOM — which is exactly why it is a
 * separate module from the `'use client'` Button that consumes it.
 *
 * ## Anatomy
 *
 *   buttonVariants({ variant, size })
 *     ├─ variant    default | highlight | destructive | outline | secondary | ghost | link
 *     ├─ size       default | xs | sm | lg | icon | icon-xs | icon-sm | icon-lg
 *     └─ fullWidth  boolean — stretches to its container (default false)
 *
 * Defaults are `variant: 'default'`, `size: 'default'`. `pagination.tsx` is
 * the in-repo example of styling an element rather than nesting a Button: its
 * `<a>` takes `buttonVariants({ variant, size })` directly. (It reaches the
 * function through `button.js`, which re-exports it — that path is
 * `'use client'`; import from this module to keep a server tree server-side.)
 *
 * ## Why half this file is comments
 *
 * Four of the seven variants carry a long note recording a measured contrast
 * failure and the rule it produced: a variant that declares its own foreground
 * must paint an opaque surface in the same state, because a button is dropped
 * onto surfaces the design system does not control. `outline` inheriting the
 * page text into a `bg-primary` section measured 1.05:1; `link` with
 * `text-primary` on the same section measured 1.00:1. `composite-contrast-lock`
 * composites every variant over every brandable backdrop, so those notes are
 * checkable rather than folklore.
 *
 * | Rule | Concept                          | Where in this file                                          |
 * | ---- | -------------------------------- | ----------------------------------------------------------- |
 * | R8   | Enums, no booleans               | `variant` and `size` are closed string enums                |
 * | R19  | Tokens only                      | `bg-primary`, `bg-destructive`, `bg-accent`, `ring-ring` |
 * | R20  | AA contrast                      | every pair composited by `composite-contrast-lock`          |
 * | R25  | Server-safe                      | no React import, no hooks, no `'use client'`                |
 */

// Server-safe button variants. The full `<Button>` component lives in
// `./button.tsx` and is `'use client'` (Base UI useRender). Variants are a
// pure CVA function — no React, no client APIs — so they can be called
// from server components when composing className strings (e.g. on a
// `<Link className={buttonVariants(...)}>` in a server-rendered page).

const buttonVariants = cva(
  "relative isolate inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-lg text-sm font-medium transition-[color,background-color,border-color,box-shadow,scale] duration-(--duration-fast) ease-enter motion-safe:active:scale-[0.97] disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-background aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/90',
        // The warm call-to-action that is NOT the brand primary: the second
        // button on a hero, "start here" beside a primary "sign up". Opaque
        // face plus its own foreground, so it holds on any section surface.
        highlight:
          'bg-highlight text-highlight-foreground hover:bg-highlight/90',
        // No `dark:bg-destructive/60` here, unlike stock shadcn — see the
        // matching note in badge.tsx. Our dark destructive token is a light
        // red tuned for AAA on near-black; muting it to 60% drops the label
        // to 4.27:1, under AA. Caught by composite-contrast-lock.
        destructive:
          'bg-destructive text-destructive-foreground hover:bg-destructive/90 focus-visible:ring-destructive',
        // `text-foreground` is NOT redundant, and neither is the ABSENCE of
        // stock shadcn's `dark:bg-input/30` / `dark:hover:bg-input/50`. Both
        // halves of that come from the same shipped defect, found twice.
        //
        // First half: `outline` paints an opaque surface (`bg-background`)
        // but was the only such variant that did not also set a foreground,
        // so it INHERITED one. Dropped inside a section that flips the text
        // colour — `<CTASection tone="primary">` is `bg-primary
        // text-primary-foreground` — the button kept the page background and
        // took the section's white text: 1.05:1, invisible.
        //
        // Second half: declaring a foreground only means something if the
        // surface under it is actually opaque. `dark:bg-input/30` overrode
        // `bg-background` with a 30% tint, so in dark mode the same
        // `bg-primary` section bled through — `#6b635a` at 30% over `#fbb99a`
        // composites to `#d09f87`, and `text-foreground` `#f0ede9` lands on
        // that at 2.00:1. The hover state was worse-shaped and identical in
        // result (`dark:hover:bg-input/50` + `hover:text-accent-foreground`,
        // 2.00:1). Dropping both makes dark match what light already did:
        // no fill, the control identified by its border — `dark:border-input`
        // is 3.35:1 on the dark background, clearing SC 1.4.11.
        //
        // The rule, stated so it is checkable: a variant that declares its own
        // foreground must paint an opaque surface in the same state, because
        // a button is dropped onto surfaces the DS does not control. Locked by
        // composite-contrast-lock, which composites every variant over every
        // brandable backdrop rather than over the page background.
        outline:
          'border bg-background text-foreground shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input',
        secondary:
          'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        // No `dark:hover:bg-accent/50` here, for the reason spelled out on
        // `outline`: it declares `hover:text-accent-foreground`, so a 50% hover
        // surface let a `bg-primary` section through at 3.07:1. Opaque
        // `bg-accent` carries its own foreground at 10.46:1 in both schemes.
        // At rest `ghost` declares neither colour and inherits both, which is
        // the variant's whole point and is safe anywhere.
        ghost: 'hover:bg-accent hover:text-accent-foreground',
        // Inherits its colour, and is underlined at rest rather than only on
        // hover. Stock shadcn is `text-primary … hover:underline`, which is
        // the same defect as the two above in its purest form: a declared
        // foreground over a surface the variant does not paint. `text-primary`
        // on a `<CTASection tone="primary">` is `#7d350c` on `#7d350c` —
        // 1.00:1, the button is literally the same colour as the section.
        //
        // A variant with no surface of its own cannot name a colour; the only
        // safe foreground is the inherited one, which is by construction the
        // pair its surface was measured with. That leaves the underline to
        // carry the affordance, so it has to be there at rest — which also
        // retires a colour-only link cue (WCAG 1.4.1) and matches how `Prose`
        // already renders links. `decoration-from-font` is Prose's too; hover
        // thickens the rule instead of shifting the hue, because any hue we
        // could shift to reintroduces the bug.
        // A link does not press like a button: it keeps its size.
        link: 'underline underline-offset-4 decoration-from-font hover:decoration-2 motion-safe:active:scale-100',
      },
      size: {
        default: 'h-control px-4 py-2 has-[>svg]:px-3',
        xs: "h-control-xs gap-1 rounded-lg px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: 'h-control-sm rounded-lg gap-1.5 px-3 has-[>svg]:px-2.5',
        lg: 'h-control-lg rounded-lg px-6 has-[>svg]:px-4',
        icon: 'size-control',
        'icon-xs': "size-control-xs rounded-lg [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-control-sm',
        'icon-lg': 'size-control-lg',
      },
      // R8: a boolean, default false, no `is` prefix. Replaces `className="w-full"`
      // at call sites (sign-in-form, newsletter-form) — MUI `fullWidth`, Primer `block`.
      fullWidth: {
        true: 'w-full',
        false: '',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
      fullWidth: false,
    },
  },
);

export { buttonVariants };
export type { VariantProps };
